import { chromium } from 'playwright';

const URL = 'http://localhost:5173/';
const results = [];
const check = (name, cond, extra = '') => {
  results.push({ name, ok: !!cond });
  console.log(`${cond ? 'PASS' : 'FAIL'} ${name}${extra ? ' — ' + extra : ''}`);
};

const browser = await chromium.launch();
const bodyTheme = (page) =>
  page.evaluate(() => [...document.body.classList].filter((c) => c.startsWith('g-root_theme_')).join(','));
const bodyBg = (page) => page.evaluate(() => getComputedStyle(document.body).backgroundColor);
const storedMode = (page) => page.evaluate(() => localStorage.getItem('theme-mode'));
const checkedOption = (page) =>
  page.evaluate(() => document.querySelector('input[name="theme"]:checked')?.value ?? null);

// 1. Fresh profile: default is light, nothing stored yet.
{
  const ctx = await browser.newContext({ colorScheme: 'light' });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
  await page.goto(URL);
  await page.waitForSelector('input[name="theme"]');
  check('default theme is light on fresh profile', (await bodyTheme(page)) === 'g-root_theme_light', await bodyTheme(page));
  check('nothing stored before user action', (await storedMode(page)) === null);

  // 2. Switch to dark via the UI.
  await page.getByText('Dark', { exact: true }).click();
  check('clicking Dark applies dark class', (await bodyTheme(page)) === 'g-root_theme_dark', await bodyTheme(page));
  check('clicking Dark persists to localStorage', (await storedMode(page)) === 'dark', await storedMode(page));
  const darkBg = await bodyBg(page);
  check('dark body background is not white', darkBg !== 'rgb(255, 255, 255)', darkBg);

  // 3. Reload restores dark.
  await page.reload();
  await page.waitForSelector('input[name="theme"]');
  check('after reload: dark class restored', (await bodyTheme(page)) === 'g-root_theme_dark', await bodyTheme(page));
  check('after reload: Dark option is checked', (await checkedOption(page)) === 'dark', await checkedOption(page));
  check('after reload: background matches dark', (await bodyBg(page)) === darkBg, await bodyBg(page));

  // 4. Inline pre-paint script: block the React bundle, the theme class must still be set.
  await page.route('**/src/main.tsx', (route) => route.abort());
  await page.goto(URL + '?nojs=1', { waitUntil: 'domcontentloaded' });
  check(
    'pre-paint script applies dark class without React bundle',
    (await bodyTheme(page)) === 'g-root_theme_dark',
    await bodyTheme(page),
  );
  await page.unroute('**/src/main.tsx');

  // 5. Switch to System and check it follows OS preference.
  await page.goto(URL);
  await page.waitForSelector('input[name="theme"]');
  await page.getByText('System', { exact: true }).click();
  check('System stored as "system"', (await storedMode(page)) === 'system', await storedMode(page));
  check('System with OS light -> light class', (await bodyTheme(page)) === 'g-root_theme_light', await bodyTheme(page));
  await page.emulateMedia({ colorScheme: 'dark' });
  await page.waitForTimeout(200);
  check('System follows OS change to dark', (await bodyTheme(page)) === 'g-root_theme_dark', await bodyTheme(page));
  await page.reload();
  await page.waitForSelector('input[name="theme"]');
  check('System survives reload', (await storedMode(page)) === 'system' && (await checkedOption(page)) === 'system');
  check('System on reload with OS dark -> dark class', (await bodyTheme(page)) === 'g-root_theme_dark', await bodyTheme(page));

  // 6. Pre-paint script with system mode and OS dark (React blocked).
  await page.route('**/src/main.tsx', (route) => route.abort());
  await page.goto(URL + '?nojs=2', { waitUntil: 'domcontentloaded' });
  check('pre-paint script resolves system -> dark', (await bodyTheme(page)) === 'g-root_theme_dark', await bodyTheme(page));
  await page.unroute('**/src/main.tsx');

  check('no page/console errors', errors.length === 0, errors.join(' | '));
  await ctx.close();
}

// 7. Invalid stored value falls back to light.
{
  const ctx = await browser.newContext();
  const page = await ctx.newPage();
  await page.goto(URL);
  await page.evaluate(() => localStorage.setItem('theme-mode', 'purple'));
  await page.reload();
  await page.waitForSelector('input[name="theme"]');
  check('invalid stored value -> light', (await bodyTheme(page)) === 'g-root_theme_light', await bodyTheme(page));
  check('invalid stored value -> no option checked as "purple"', (await checkedOption(page)) === 'light', await checkedOption(page));
  await ctx.close();
}

// 8. Storage disabled: app still works, no crash.
{
  const ctx = await browser.newContext();
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  await page.addInitScript(() => {
    Object.defineProperty(window, 'localStorage', {
      get() { throw new DOMException('denied', 'SecurityError'); },
    });
  });
  await page.goto(URL);
  await page.waitForSelector('input[name="theme"]');
  await page.getByText('Dark', { exact: true }).click();
  check('storage denied: switching still applies dark', (await bodyTheme(page)) === 'g-root_theme_dark', await bodyTheme(page));
  check('storage denied: no page errors', errors.length === 0, errors.join(' | '));
  await ctx.close();
}

await browser.close();
const failed = results.filter((r) => !r.ok).length;
console.log(`\n${results.length - failed}/${results.length} passed`);
process.exit(failed ? 1 : 0);

