// @vitest-environment jsdom
// TEMPORARY verification test — deleted after the run.
import * as fs from 'node:fs';
import * as path from 'node:path';
import * as React from 'react';
import ReactDOM from 'react-dom/client';
import { act } from 'react-dom/test-utils';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

(globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;

function mockMatchMedia(dark: boolean) {
  window.matchMedia = vi.fn().mockImplementation((query: string) => ({
    matches: dark && query.includes('dark'),
    media: query,
    onchange: null,
    addEventListener: () => {},
    removeEventListener: () => {},
    addListener: () => {},
    removeListener: () => {},
    dispatchEvent: () => false,
  })) as any;
}

// Mount the real app tree the same way src/main.tsx does (fresh module graph = "page load").
async function loadPage() {
  vi.resetModules();
  const { App } = await import('../src/App');
  const { ThemeModeProvider } = await import('../src/themeMode');
  const container = document.createElement('div');
  document.body.appendChild(container);
  const root = ReactDOM.createRoot(container);
  await act(async () => {
    root.render(
      <React.StrictMode>
        <ThemeModeProvider>
          <App />
        </ThemeModeProvider>
      </React.StrictMode>,
    );
  });
  return {
    unmount: () => act(() => root.unmount()),
    container,
  };
}

const bodyThemeClasses = () =>
  [...document.body.classList].filter((c) => c.startsWith('g-root_theme_')).join(',');
const checked = () => document.querySelector<HTMLInputElement>('input[name="theme"]:checked')?.value ?? null;
const stored = () => localStorage.getItem('theme-mode');

function pick(value: 'light' | 'dark' | 'system') {
  const input = document.querySelector<HTMLInputElement>(`input[name="theme"][value="${value}"]`);
  if (!input) throw new Error(`no radio for ${value}`);
  act(() => {
    input.click();
  });
}

// Pull the inline pre-paint script out of the real index.html.
function runPrePaintScript() {
  const html = fs.readFileSync(path.resolve(__dirname, '../index.html'), 'utf8');
  const scripts = [...html.matchAll(/<script>([\s\S]*?)<\/script>/g)].map((m) => m[1]);
  expect(scripts.length).toBe(1);
  // eslint-disable-next-line no-new-func
  new Function(scripts[0])();
}

describe('theme switcher', () => {
  let page: { unmount: () => Promise<void> | void } | undefined;

  beforeEach(() => {
    localStorage.clear();
    document.body.className = '';
    document.body.innerHTML = '';
    mockMatchMedia(false);
  });

  afterEach(async () => {
    if (page) await page.unmount();
    page = undefined;
    document.body.innerHTML = '';
  });

  it('defaults to light on a fresh profile and stores nothing', async () => {
    page = await loadPage();
    expect(bodyThemeClasses()).toBe('g-root_theme_light');
    expect(checked()).toBe('light');
    expect(stored()).toBeNull();
  });

  it('selecting Dark applies the class and persists it', async () => {
    page = await loadPage();
    pick('dark');
    expect(bodyThemeClasses()).toBe('g-root_theme_dark');
    expect(stored()).toBe('dark');
    expect(checked()).toBe('dark');
  });

  it('restores Dark after a "reload" (new module graph, same localStorage)', async () => {
    page = await loadPage();
    pick('dark');
    await page.unmount();
    document.body.innerHTML = '';
    page = await loadPage();
    expect(bodyThemeClasses()).toBe('g-root_theme_dark');
    expect(checked()).toBe('dark');
  });

  it('switching back to Light overwrites the stored value', async () => {
    page = await loadPage();
    pick('dark');
    pick('light');
    expect(stored()).toBe('light');
    await page.unmount();
    document.body.innerHTML = '';
    page = await loadPage();
    expect(bodyThemeClasses()).toBe('g-root_theme_light');
  });

  it('System follows OS preference and survives reload', async () => {
    mockMatchMedia(true);
    page = await loadPage();
    pick('system');
    expect(stored()).toBe('system');
    expect(bodyThemeClasses()).toBe('g-root_theme_dark');
    await page.unmount();
    document.body.innerHTML = '';
    page = await loadPage();
    expect(checked()).toBe('system');
    expect(bodyThemeClasses()).toBe('g-root_theme_dark');
  });

  it('invalid stored value falls back to light', async () => {
    localStorage.setItem('theme-mode', 'purple');
    page = await loadPage();
    expect(bodyThemeClasses()).toBe('g-root_theme_light');
    expect(checked()).toBe('light');
  });

  it('keeps working when localStorage throws', async () => {
    const spyGet = vi.spyOn(Storage.prototype, 'getItem').mockImplementation(() => {
      throw new DOMException('denied', 'SecurityError');
    });
    const spySet = vi.spyOn(Storage.prototype, 'setItem').mockImplementation(() => {
      throw new DOMException('denied', 'SecurityError');
    });
    try {
      page = await loadPage();
      expect(bodyThemeClasses()).toBe('g-root_theme_light');
      pick('dark');
      expect(bodyThemeClasses()).toBe('g-root_theme_dark');
    } finally {
      spyGet.mockRestore();
      spySet.mockRestore();
    }
  });
});

describe('index.html pre-paint script', () => {
  beforeEach(() => {
    localStorage.clear();
    document.body.className = '';
    mockMatchMedia(false);
  });

  it('applies stored dark before React runs', () => {
    localStorage.setItem('theme-mode', 'dark');
    runPrePaintScript();
    expect(bodyThemeClasses()).toBe('g-root_theme_dark');
    expect(document.body.classList.contains('g-root')).toBe(true);
  });

  it('applies light when nothing stored', () => {
    runPrePaintScript();
    expect(bodyThemeClasses()).toBe('g-root_theme_light');
  });

  it('resolves system via OS preference (dark)', () => {
    localStorage.setItem('theme-mode', 'system');
    mockMatchMedia(true);
    runPrePaintScript();
    expect(bodyThemeClasses()).toBe('g-root_theme_dark');
  });

  it('resolves system via OS preference (light)', () => {
    localStorage.setItem('theme-mode', 'system');
    mockMatchMedia(false);
    runPrePaintScript();
    expect(bodyThemeClasses()).toBe('g-root_theme_light');
  });

  it('ignores invalid stored value', () => {
    localStorage.setItem('theme-mode', 'evil"><b>');
    runPrePaintScript();
    expect(bodyThemeClasses()).toBe('g-root_theme_light');
  });

  it('does not throw when storage is denied', () => {
    const spy = vi.spyOn(Storage.prototype, 'getItem').mockImplementation(() => {
      throw new DOMException('denied', 'SecurityError');
    });
    try {
      expect(() => runPrePaintScript()).not.toThrow();
      expect(bodyThemeClasses()).toBe('g-root_theme_light');
    } finally {
      spy.mockRestore();
    }
  });
});

